":{"description":"A unique identifier for the agent's skill.","type":"string"},"inputModes":{"description":"The set of supported input MIME types for this skill, overriding the agent's defaults.","items":{"type":"string"},"type":"array"},"name":{"description":"A human-readable name for the skill.","type":"string"},"outputModes":{"description":"The set of supported output MIME types for this skill, overriding the agent's defaults.","items":{"type":"string"},"type":"array"},"security":{"description":"Security schemes necessary for the agent to leverage this skill.\nAs in the overall AgentCard.security, this list represents a logical OR of security\nrequirement objects. Each object is a set of security schemes that must be used together\n(a logical AND).","examples":[[{"google":["oidc"]}]],"items":{"additionalProperties":{"items":{"type":"string"},"type":"array"},"type":"object"},"type":"array"},"tags":{"description":"A set of keywords describing the skill's capabilities.","examples":[["cooking","customer support","billing"]],"items":{"type":"string"},"type":"array"}},"required":["description","id","name","tags"],"type":"object"},"AgentExtension":{"description":"A declaration of a protocol extension supported by an Agent.","examples":[{"description":"Google OAuth 2.0 authentication","required":false,"uri":"https://developers.google.com/identity/protocols/oauth2"}],"properties":{"description":{"description":"A human-readable description of how this agent uses the extension.","type":"string"},"params":{"additionalProperties":{},"description":"Optional, extension-specific configuration parameters.","type":"object"},"required":{"description":"If true, the client must understand and comply with the extension's requirements\nto interact with the agent.","type":"boolean"},"uri":{"description":"The unique URI identifying the extension.","type":"string"}},"required":["uri"],"type":"object"},"AgentCapabilities":{"description":"Defines optional capabilities supported by an agent.