en on a per-skill basis.","items":{"type":"string"},"type":"array"},"description":{"description":"A human-readable description of the agent, assisting users and other agents\nin understanding its purpose.","examples":["Agent that helps users with recipes and cooking."],"type":"string"},"documentationUrl":{"description":"An optional URL to the agent's documentation.","type":"string"},"iconUrl":{"description":"An optional URL to an icon for the agent.","type":"string"},"name":{"description":"A human-readable name for the agent.","examples":["Recipe Agent"],"type":"string"},"preferredTransport":{"default":"JSONRPC","description":"The transport protocol for the preferred endpoint (the main 'url' field).\nIf not specified, defaults to 'JSONRPC'.\n\nIMPORTANT: The transport specified here MUST be available at the main 'url'.\nThis creates a binding between the main URL and its supported transport protocol.\nClients should prefer this transport and URL combination when both are supported.","examples":["JSONRPC","GRPC","HTTP+JSON"],"type":"string"},"protocolVersion":{"default":"0.3.0","description":"The version of the A2A protocol this agent supports.","type":"string"},"provider":{"$ref":"#/definitions/AgentProvider","description":"Information about the agent's service provider."},"security":{"description":"A list of security requirement objects that apply to all agent interactions. Each object\nlists security schemes that can be used. Follows the OpenAPI 3.0 Security Requirement Object.\nThis list can be seen as an OR of ANDs. Each object in the list describes one possible\nset of security requirements that must be present on a request. This allows specifying,\nfor example, \"callers must either use OAuth OR an API Key AND mTLS.\"","examples":[[{"oauth":["read"]},{"api-key":[],"mtls":[]}]],"items":{"additionalProperties":{"items":{"type":"string"},"type":"array"},"type":"object"},"type":"array"},"securitySchemes":{"additionalProperties":{"$ref":"#/definitions/SecurityScheme"},"description":"A declaration of the security schemes available to authorize requests. The key is the\nscheme name. Follows the OpenAPI 3.0 Security Scheme Object.","type":"object"},"signatures":{"description":"JSON Web Signatures computed for this AgentCard.","items":{"$ref":"#/definitions/AgentCardSignature"},"type":"array"},"skills":{"description":"The set of skills, or distinct capabilities, that the agent can perform.","items":{"$ref":"#/definitions/AgentSkill"},"type":"array"},"supportsAuthenticatedExtendedCard":{"description":"If true, the agent can provide an extended agent card with additional details\nto authenticated users. Defaults to false.","type":"boolean"},"url":{"description":"The preferred endpoint URL for interacting with the agent.\nThis URL MUST support the transport specified by 'preferredTransport'.","examples":["https://api.example.com/a2a/v1"],"type":"string"},"version":{"description":"The agent's own version number. The format is defined by the provider.","examples":["1.0.0"],"type":"string"}},"required":["capabilities","defaultInputModes","defaultOutputModes","description","name","protocolVersion","skills","url","version"],"type":"object"},"AgentInterface":{"description":"Declares a combination of a target URL and a transport protocol for interacting with the agent.\nThis allows agents to expose the same functionality over multiple transport mechanisms.","properties":{"transport":{"description":"The transport protocol supported at this URL.","examples":["JSONRPC","GRPC","HTTP+JSON"],"type":"string"},"url":{"description":"The URL where this interface is available. Must be a valid absolute HTTPS URL in production.","examples":["https://api.example.com/a2a/v1","https://grpc.example.com/a2a","https://rest.example.com/v1"],"type":"string"}},"required":["transport","url"],"type":"object"},"SecurityScheme":{"anyOf":[{"$ref":"#/definitions/APIKeySecurityScheme"},{"$ref":"#/definitions/HTTPAuthSecurityScheme"},{"$ref":"#/definitions/OAuth2Securi