ditionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope\nname and a short description for it.","type":"object"}},"required":["authorizationUrl","scopes"],"type":"object"},"MutualTLSSecurityScheme":{"description":"Defines a security scheme using mTLS authentication.","properties":{"description":{"description":"An optional description for the security scheme.","type":"string"},"type":{"const":"mutualTLS","description":"The type of the security scheme. Must be 'mutualTLS'.","type":"string"}},"required":["type"],"type":"object"},"OAuth2SecurityScheme":{"description":"Defines a security scheme using OAuth 2.0.","properties":{"description":{"description":"An optional description for the security scheme.","type":"string"},"flows":{"$ref":"#/definitions/OAuthFlows","description":"An object containing configuration information for the supported OAuth 2.0 flows."},"oauth2MetadataUrl":{"description":"URL to the oauth2 authorization server metadata\n[RFC8414](https://datatracker.ietf.org/doc/html/rfc8414). TLS is required.","type":"string"},"type":{"const":"oauth2","description":"The type of the security scheme. Must be 'oauth2'.","type":"string"}},"required":["flows","type"],"type":"object"},"OAuthFlows":{"description":"Defines the configuration for the supported OAuth 2.0 flows.","properties":{"authorizationCode":{"$ref":"#/definitions/AuthorizationCodeOAuthFlow","description":"Configuration for the OAuth Authorization Code flow. Previously called accessCode in OpenAPI 2.0."},"clientCredentials":{"$ref":"#/definitions/ClientCredentialsOAuthFlow","description":"Configuration for the OAuth Client Credentials flow. Previously called application in OpenAPI 2.0."},"implicit":{"$ref":"#/definitions/ImplicitOAuthFlow","description":"Configuration for the OAuth Implicit flow."},"password":{"$ref":"#/definitions/PasswordOAuthFlow","description":"Configuration for the OAuth Resource Owner Password flow."}},"type":"object"},"AuthorizationCodeOAuthFlow":{"description":"Defines configuration details for the OAuth 2.0 Authorization Code flow.","properties":{"authorizationUrl":{"description":"The authorization URL to be used for this flow.\nThis MUST be a URL and use TLS.","type":"string"},"refreshUrl":{"description":"The URL to be used for obtaining refresh tokens.\nThis MUST be a URL and use TLS.","type":"string"},"scopes":{"additionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope\nname and a short description for it.","type":"object"},"tokenUrl":{"description":"The token URL to be used for this flow.\nThis MUST be a URL and use TLS.","type":"string"}},"required":["authorizationUrl","scopes","tokenUrl"],"type":"object"},"ClientCredentialsOAuthFlow":{"description":"Defines configuration details for the OAuth 2.0 Client Credentials flow.","properties":{"refreshUrl":{"description":"The URL to be used for obtaining refresh tokens. This MUST be a URL.","type":"string"},"scopes":{"additionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope\nname and a short description for it.","type":"object"},"tokenUrl":{"description":"The token URL to be used for this flow. This MUST be a URL.","type":"string"}},"required":["scopes","tokenUrl"],"type":"object"},"OpenIdConnectSecurityScheme":{"description":"Defines a security scheme using OpenID Connect.","properties":{"description":{"description":"An optional description for the security scheme.","type":"string"},"openIdConnectUrl":{"description":"The OpenID Connect Discovery URL for the OIDC provider's metadata.","type":"string"},"type":{"const":"openIdConnect","description":"The type of the security scheme. Must be 'openIdConnect'.","type":"string"}},"required":["openIdConnectUrl","type"],"type":"object"},"PasswordOAuthFlow":{"description":"Defines configuration details for the OAuth 2.0 Resource Owner Password flow.","properties":{"refreshUrl":{"description":"The URL to be used for obtaining refresh tokens. This MUST be a URL.","type":"string"},"scopes":{"additionalProperties":{"type":"string"},"description":"The available scopes for the OAuth2 security scheme. A map between the scope\nname and a short description for it.","type":"object"},"tokenUrl":{"description":"The token URL to be used for this flow. This MUST be a URL.","type":"string"}},"required":["scopes","tokenUrl"],"type":"object"}}}""".stripMargin

